UPDATE language_levels ll JOIN languages lang ON lang.id=ll.language_id
SET ll.audio_status=IF(NOT EXISTS (
  SELECT 1 FROM v_audio_generation_manifest m
  WHERE m.language_code=lang.code AND m.cefr_level=ll.cefr_level AND m.audio_is_current<>1
),'ready','pending')
WHERE lang.code='de' AND ll.cefr_level='A1' AND ll.status='final';
UPDATE languages lang SET lang.status='audio_ready'
WHERE lang.code='de' AND NOT EXISTS (SELECT 1 FROM language_levels ll WHERE ll.language_id=lang.id AND (ll.status<>'final' OR ll.audio_status<>'ready'));
UPDATE lessons le JOIN _audio_mapping_lesson_status s ON s.lesson_id=le.id
SET le.status=s.original_status
WHERE NOT (le.status <=> s.original_status);
DROP TEMPORARY TABLE IF EXISTS _audio_mapping_lesson_status;
COMMIT;
